def dp(n, k, a, b):
	dp = [[-1 for _ in range(1601)] for __ in range(k + 1)]
	dp[0][0] = 0
	for i in range(n):
		for j in range(k - 1, -1, -1):
			for s in range(1601):
				if dp[j][s] != -1:
					dp[j + 1][s + a[i]] = max(dp[j][s] + b[i], dp[j + 1][s + a[i]])
	ans = 0
	for s in range(0, 1601):
		ans = max(ans, min(s, dp[k][s]))
	return ans
t = int(input())
for _ in range(t):
	(n, k) = map(int, input().split())
	a = [int(i) for i in input().split()]
	b = [int(i) for i in input().split()]
	print(dp(n, k, a, b))
